#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn preserves_order() {
        assert_eq!(parallel_map(vec![1, 2, 3, 4], 2, |x| x * x), vec![1, 4, 9, 16]);
    }

    #[test]
    fn order_with_uneven_work() {
        let inputs: Vec<i64> = (0..40).collect();
        let out = parallel_map(inputs.clone(), 4, |x| {
            std::thread::sleep(Duration::from_millis(((40 - x) % 5) as u64));
            x * 10 + 1
        });
        assert_eq!(out, inputs.iter().map(|x| x * 10 + 1).collect::<Vec<_>>());
    }

    #[test]
    fn edge_cases() {
        assert_eq!(parallel_map(vec![], 3, |x| x), Vec::<i64>::new());
        assert_eq!(parallel_map(vec![5, 6], 0, |x| -x), vec![-5, -6]);
        assert_eq!(parallel_map(vec![9], 8, |x| x + 1), vec![10]);
    }

    #[test]
    fn closure_captures_state() {
        let offset = 100;
        assert_eq!(parallel_map(vec![1, 2, 3], 3, move |x| x + offset), vec![101, 102, 103]);
    }

    #[test]
    fn uses_bounded_pool() {
        let inputs: Vec<i64> = (0..200).collect();
        let used = count_workers_used(inputs, 3);
        assert!(used >= 1 && used <= 3, "used {} workers", used);
        assert_eq!(count_workers_used(vec![1, 2, 3], 0), 1);
        assert_eq!(count_workers_used(vec![], 4), 0);
    }
}
